What is printed here?

```cpp
#include <iostream>

struct Temp {
    Temp() { std::cout << "alive\n"; }
    ~Temp() { std::cout << "dead\n"; }
};

int main() {
    std::cout << "before\n";
    Temp();
    std::cout << "after\n";
    return 0;
}
```

